import math

def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    # Check divisors up to sqrt(n)
    limit = int(math.sqrt(n))
    for i in range(1, limit + 1):
        if n % i == 0:
            # If i is a divisor, then n/i is also a divisor
            if i * i == n:
                count += 1  # Perfect square case
            else:
                count += 2  # Pair of divisors (i and n/i)
    return count

results = []
for k in range(1, 16):
    N = 2 * (k**3)
    d_Nk3 = count_divisors(N)
    two_k = 2 * k
    is_equal = d_Nk3 == two_k
    results.append({
        'k': k,
        '2k': two_k,
        'd(2k^3)': d_Nk3,
        'equal': is_equal
    })

# Print results in a clear format for note recording
print("k | 2k | d(2k^3) | Equal?")
print("-" * 35)
for r in results:
    status = "Yes" if r['equal'] else "No"
    print(f"{r['k']:<2} | {r['2k']:<2} | {r['d(2k^3)']:<7} | {status}")

